// In-memory demo only; never calls a trading API or persists account data.
const demoStocks=[{name:'가상 종목 A',quantity:20,price:85000},{name:'가상 종목 B',quantity:5,price:315000},{name:'가상 종목 C',quantity:10,price:252000}];
let demoCash=4450000,side='buy',pending=null,processing=false;
const $=id=>document.getElementById(id),money=n=>n.toLocaleString('ko-KR')+'원';
function totals(stock,q){const gross=q*stock.price,fee=Math.round(gross*.00015),tax=side==='sell'?Math.round(gross*.0018):0;return {gross,fee,tax,settlement:side==='buy'?gross+fee:gross-fee-tax};}
function assets(){return demoCash+demoStocks.reduce((sum,s)=>sum+s.price*s.quantity,0);}
function errorFor(stock,q){if(!Number.isSafeInteger(q)||q<1)return '1주 이상의 정수 수량을 입력하세요.';const t=totals(stock,q);if(!Number.isSafeInteger(t.gross))return '수량이 너무 큽니다. 더 작은 수량을 입력하세요.';if(side==='sell')return q>stock.quantity?`보유 수량은 ${stock.quantity}주입니다. 그 이하로 입력하세요.`:'';if(t.settlement>demoCash)return '현금이 부족합니다. 수량을 줄이거나 최대 수량을 눌러주세요.';if((stock.quantity+q)*stock.price>(assets()-t.fee)*.3)return '한 종목의 투자 한도(총자산의 30%)를 넘습니다. 수량을 줄여주세요.';return '';}
function maxQuantity(stock){if(side==='sell')return stock.quantity;let low=0,high=Math.floor(demoCash/stock.price);while(low<high){const mid=Math.ceil((low+high)/2);if(errorFor(stock,mid))high=mid-1;else low=mid;}return low;}
function render(){const stock=demoStocks[Number($('stock').value)],q=$('quantity').value.trim()===''?NaN:Number($('quantity').value),error=errorFor(stock,q),valid=Number.isSafeInteger(q)&&q>0&&Number.isSafeInteger(q*stock.price),t=valid?totals(stock,q):null;pending=null;$('price').textContent=money(stock.price);$('held').textContent=stock.quantity+'주';$('buy').setAttribute('aria-pressed',String(side==='buy'));$('sell').setAttribute('aria-pressed',String(side==='sell'));$('quantity-hint').textContent=`지금 ${side==='buy'?'살':'팔'} 수 있는 최대 수량: ${maxQuantity(stock)}주`;$('error').textContent=error;$('quantity').setAttribute('aria-invalid',String(Boolean(error)));for(const key of ['gross','fee','tax','settlement'])$(key).textContent=t?money(t[key]):'—';$('tax-row').hidden=side!=='sell';$('total-label').textContent=side==='buy'?'총 결제 금액':'받을 금액 (비용 제외 후)';$('cash').textContent=money(demoCash);$('after').textContent=!error?money(side==='buy'?demoCash-t.settlement:demoCash+t.settlement):'—';$('review').textContent=side==='buy'?'매수 내용 확인':'매도 내용 확인';$('review').disabled=Boolean(error);}
function setQuantity(q){$('quantity').value=String(q);render();}
$('stock').addEventListener('change',()=>setQuantity(1));$('quantity').addEventListener('input',render);$('buy').addEventListener('click',()=>{side='buy';render();});$('sell').addEventListener('click',()=>{side='sell';render();});$('minus').addEventListener('click',()=>setQuantity(Math.max(1,(Number($('quantity').value)||1)-1)));$('plus').addEventListener('click',()=>setQuantity((Number($('quantity').value)||0)+1));$('one').addEventListener('click',()=>setQuantity(1));$('ten').addEventListener('click',()=>setQuantity(10));$('max').addEventListener('click',()=>setQuantity(maxQuantity(demoStocks[Number($('stock').value)])));
$('review').addEventListener('click',()=>{const index=Number($('stock').value),q=Number($('quantity').value),stock=demoStocks[index];if(errorFor(stock,q))return;pending={index,q,side,...totals(stock,q)};$('confirm-text').textContent=`${stock.name} ${q}주 ${side==='buy'?'매수':'매도'} · ${side==='buy'?'결제':'받을'} 금액 ${money(pending.settlement)} (수수료 ${money(pending.fee)}${side==='sell'?', 세금 '+money(pending.tax):''})`;$('confirm').showModal();});
$('cancel').addEventListener('click',()=>{$('confirm').close();pending=null;});$('confirm').addEventListener('cancel',()=>{pending=null;});
$('complete').addEventListener('click',()=>{if(processing||!pending)return;processing=true;$('complete').disabled=true;const order=pending,stock=demoStocks[order.index];if(errorFor(stock,order.q)){pending=null;$('confirm').close();render();processing=false;$('complete').disabled=false;return;}demoCash+=order.side==='buy'?-order.settlement:order.settlement;stock.quantity+=order.side==='buy'?order.q:-order.q;const li=document.createElement('li');li.textContent=`${stock.name} ${order.q}주 ${order.side==='buy'?'매수':'매도'} 연습 완료`;const detail=document.createElement('small');detail.textContent=`${order.side==='buy'?'결제':'받은'} 금액 ${money(order.settlement)} · 수수료 ${money(order.fee)}${order.side==='sell'?' · 세금 '+money(order.tax):''}`;li.append(detail);$('history').prepend(li);$('empty').hidden=true;$('result').textContent='연습 주문이 완료되었습니다. 아래에서 결과를 확인하세요.';pending=null;$('confirm').close();render();processing=false;$('complete').disabled=false;});render();
